import json

from shelf import books, report


def setup_function():
    books.clear()


def test_by_author_counts_books_per_author():
    books.add("Dune", "Frank Herbert")
    books.add("Dune Messiah", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert report.by_author() == {"Frank Herbert": 2, "Jane Austen": 1}


def test_by_author_on_empty_shelf():
    assert report.by_author() == {}


def test_by_author_returns_plain_dict():
    books.add("Dune", "Frank Herbert")
    assert type(report.by_author()) is dict


def test_as_json_has_summary_and_by_author():
    books.add("Dune", "Frank Herbert")
    books.add("Dune Messiah", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert json.loads(report.as_json()) == {
        "summary": "3 books",
        "by_author": {"Frank Herbert": 2, "Jane Austen": 1},
    }


def test_as_json_on_empty_shelf():
    assert json.loads(report.as_json()) == {"summary": "0 books", "by_author": {}}


def test_as_json_is_deterministic():
    books.add("Emma", "Jane Austen")
    books.add("Dune", "Frank Herbert")
    assert report.as_json() == (
        '{"by_author": {"Frank Herbert": 1, "Jane Austen": 1}, "summary": "2 books"}'
    )

"""One-line summary of the catalogue."""
import json
from collections import Counter

from shelf import books


def summary():
    return "%d books" % len(books.all_books())


def by_author():
    return dict(Counter(b["author"] for b in books.all_books()))


def as_json():
    return json.dumps({"summary": summary(), "by_author": by_author()}, sort_keys=True)
